// nodePolicyEval is a node that completes the building of the policy graph,
// with incoming edges from the resource graph so that policy evaluation
// is performed only when the resource graph is complete.
type nodePolicyEval struct{}

var _ GraphNodeDynamicExpandable = (*nodePolicyEval)(nil)
var _ dag.TolerantVertex = (*nodePolicyEval)(nil)

func (n *nodePolicyEval) Name() string {
	return "(evaluate policies)"
}

func (n *nodePolicyEval) DynamicExpand(ctx EvalContext) (*Graph, tfdiags.Diagnostics) {
	policyGraph := ctx.PolicyGraph()
	if policyGraph == nil {
		log.Printf("[DEBUG] policyGraph is nil")
		return nil, nil
	}
	// Close the changes/state objects to prevent writes during policy evaluation.
	// This is safe to do because policy evaluation is the final step in the plan/apply process.
	// If any future nodes attempt to write to these states, they will panic.
	ctx.Changes().Close()
	ctx.State().Close()

	_, span := tracer().Start(ctx.StopCtx(), "terraform.policy.evaluate")
	policyGraph.span = span

	// Add a finish node that depends on every policy node, so it runs last and
	// ends the phase span once all policy evaluation has completed.
	finish := &nodePolicyEvalFinish{span: policyGraph.span}
	policyGraph.graph.Add(finish)
	for pn := range policyGraph.graph.VerticesSeq() {
		if _, ok := pn.(*nodeResourcePolicy); !ok {
			continue
		}
		// finish depends on pn, so pn runs first and finish runs after.
		policyGraph.graph.Connect(dag.BasicEdge(finish, pn))
	}

	// ensure the graph has a single root
	addRootNodeToGraph(&policyGraph.graph)
	return &policyGraph.graph, nil
}

// AllowUpstreamFailure allows failures from upstream nodes to be tolerated
// so that the policy evaluation can proceed even if some resource instance nodes
// evaluated with error diagnostics.
func (n *nodePolicyEval) AllowUpstreamFailure(dep dag.Vertex) bool {
	_, ok := dep.(GraphNodeConfigResource)
	return ok
}

// nodePolicyEvalFinish is a sentinel node appended to the policy subgraph that
// runs after every policy node and ends the policy-execution phase span. It
// must tolerate upstream failures so the span is still closed even if a policy
// node returned error diagnostics.
type nodePolicyEvalFinish struct {
	span trace.Span
}

var _ GraphNodeExecutable = (*nodePolicyEvalFinish)(nil)
var _ dag.TolerantVertex = (*nodePolicyEvalFinish)(nil)

func (n *nodePolicyEvalFinish) Name() string {
	return "(policy evaluation complete)"
}

func (n *nodePolicyEvalFinish) Execute(ctx EvalContext, op walkOperation) tfdiags.Diagnostics {
	n.span.End()
	return nil
}

// AllowUpstreamFailure tolerates failures from the policy nodes so the phase
// span is always ended.
func (n *nodePolicyEvalFinish) AllowUpstreamFailure(dep dag.Vertex) bool {
	_, ok := dep.(*nodeResourcePolicy)
	return ok
}

// EvalPolicy evaluates the provider policy.
// Contrary to resource policy evaluation, provider policy evaluation is done inline,
// allowing us to block the evaluation of the provider's resources within the graph if the policy fails.
// Provider policies have no support for callback functions, so we do not need to worry about
// them retrieving objects that are not yet available in the state.
func (n *NodeApplyableProvider) EvalPolicy(ctx EvalContext, attrs cty.Value) tfdiags.Diagnostics {
	if ctx.PolicyClient() == nil {
		log.Printf("[DEBUG] No policy client configured, skipping policy evaluation for %s", n.Addr)
		return nil
	}

	result := ctx.PolicyClient().EvaluateProvider(ctx.StopCtx(), policy.EvaluationRequest[*proto.PolicyEvaluateProviderRequest_ProviderMetadata]{
		Target: n.Addr.Provider.Type,
		Attrs:  policy.CtyToPolicyValue(attrs),
		Meta: &proto.PolicyEvaluateProviderRequest_ProviderMetadata{
			Name:      n.Addr.Provider.Type,
			Alias:     n.Addr.Alias,
			Namespace: n.Addr.Provider.Namespace,
			Source:    n.Addr.Provider.String(),
			Version:   n.providerVersion(ctx),
		},
	})

	// if this was an "implicit provider", and we have no configuration
	// for it, There's going to be no source information for these errors.
	if n.Config != nil {
		ptr := n.Config.DeclRange.Ptr()
		for idx, diag := range result.Diagnostics {
			result.Diagnostics[idx] = diag.WithLocalRange(ptr)
		}
		for idx := range result.Enforcements {
			result.Enforcements[idx].LocalRange = ptr
		}
	}

	// always add the result to the policy results
	if ctx.PolicyResults() != nil {
		ctx.PolicyResults().AddProvider(n.Addr, result, n.Config)
	}

	return nil
}

// providerVersion returns the exact locked version for this provider from the
// dependency lock file (e.g. "5.31.0"). Returns an empty string if no lock
// file entry is available for this provider.
func (n *NodeApplyableProvider) providerVersion(ctx EvalContext) string {
	if providerLocks := ctx.ProviderLocks(); providerLocks != nil {
		if lock := providerLocks[n.Addr.Provider]; lock != nil {
			return lock.Version().String()
		}
	}
	return ""
}

			Version: func() string {
				// local modules do not have versions, so we just return
				// an empty string in that case.
				if configBundle.Version == nil {
					return ""
				}
				return configBundle.Version.String()
			}(),
		},
	})

	// add local range to diagnostics if the module call has a config body.
	if n.ModuleCall.Config != nil {
		ptr := n.ModuleCall.DeclRange.Ptr()
		for idx, diag := range result.Diagnostics {
			result.Diagnostics[idx] = diag.WithLocalRange(ptr)
		}
		for idx := range result.Enforcements {
			result.Enforcements[idx].LocalRange = ptr
		}
	}

	// always add the result to the policy results
	if ctx.PolicyResults() != nil {
		ctx.PolicyResults().AddModule(n.Addr, result, n.ModuleCall)
	}

	return nil
}

